    stringMembers.Add(member.StringKey, (member, item.Type));"}]},{"requirementItemId":null,"text":"When no constructor has [SerializationConstructor], candidate constructors are still ordered by accessibility (descending), but ties are now broken by ascending parameter count instead of descending. The first constructor tried is therefore the one with the fewest parameters.","kind":"behaviour","hunkIds":["h8"],"pathGlob":null,"citations":[{"file":"src/MessagePack.SourceGenerator/CodeAnalysis/TypeCollector.cs","side":"new","startLine":1211,"endLine":1214,"quote":".ThenBy(x => x.Parameters.Length)"},{"file":"src/MessagePack.SourceGenerator/CodeAnalysis/TypeCollector.cs","side":"old","startLine":1197,"endLine":1200,"quote":".ThenByDescending(x => x.Parameters.Length)"}]},{"requirementItemId":"F1","text":"An analyzer test expects MsgPack004 on a public property without a Key attribute in a [MessagePackObject(SuppressSourceGeneration = true)] class.","kind":"test","hunkIds":["h10"],"pathGlob":null,"citations":[{"file":"tests/MessagePack.SourceGenerator.Tests/SuppressSourceGenerationAnalyzerTests.cs","side":"new","startLine":24,"endLine":28,"quote":"public string {|MsgPack004:Member|} { get; set; }"}]},{"requirementItemId":"F1","text":"Analyzer tests expect MsgPack015 (AllowPrivate required) on the attribute of a suppressed type that has a keyed private field. They also expect MsgPack003 on a keyed member whose type is not a MessagePackObject.","kind":"test","hunkIds":["h10"],"pathGlob":null,"citations":[{"file":"tests/MessagePack.SourceGenerator.Tests/SuppressSourceGenerationAnalyzerTests.cs","side":"new","startLine":42,"endLine":46,"quote":"[{|MsgPack015:MessagePackObject(SuppressSourceGeneration = true)|}]"},{"file":"tests/MessagePack.SourceGenerator.Tests/SuppressSourceGenerationAnalyzerTests.cs","side":"new","startLine":65,"endLine":70,"quote":"public Other {|MsgPack003:Member|} { get; set; }"}]},{"requirementItemId":"N1","text":"Analyzer tests on suppressed types wi